import{_ as l,o as e,c as o,a4 as c}from"./chunks/framework.vNSRaLQv.js";const h=JSON.parse('{"title":"HomeSense-Studio v2 交接文档 — 2026-06-06","description":"","frontmatter":{"title":"HomeSense-Studio v2 交接文档 — 2026-06-06","date":"2026-06-06T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense-Studio-v2-HANDOFF-2026-06-06.md","filePath":"posts/HomeSense-Studio-v2-HANDOFF-2026-06-06.md"}'),d={name:"posts/HomeSense-Studio-v2-HANDOFF-2026-06-06.md"};function a(s,i,t,n,p,u){return e(),o("div",null,[...i[0]||(i[0]=[c(`<h1 id="homesense-studio-v2-交接文档-—-2026-06-06" tabindex="-1">HomeSense-Studio v2 交接文档 — 2026-06-06 <a class="header-anchor" href="#homesense-studio-v2-交接文档-—-2026-06-06" aria-label="Permalink to &quot;HomeSense-Studio v2 交接文档 — 2026-06-06&quot;">​</a></h1><h2 id="_0-当前上下文" tabindex="-1">0. 当前上下文 <a class="header-anchor" href="#_0-当前上下文" aria-label="Permalink to &quot;0. 当前上下文&quot;">​</a></h2><ul><li>当前主仓库：<code>D:\\files\\HomeSense-Studio-v2</code></li><li>旧仓库只做参考：<code>D:\\files\\HomeSense-Stdio</code></li><li>当前目标不是继续堆页面，而是把“设备 / 授权 / 数字孪生”的职责边界重新理顺。</li><li>用户最新明确方向： <ul><li>数字孪生先做 2D，不做 3D。</li><li>设备页要重新设计成 2D 房间 / 设备视图。</li><li>绑定关系不要堆在 2D 图上，去详情页里看。</li><li>IP 保留，但不再叫 LAN 来源。</li><li>ADB 是能力来源 / 绑定来源，不叫 LAN。</li><li>ADB 授权页只管理 ADB 端点，不管理完整设备。</li></ul></li></ul><hr><h2 id="_1-服务与验证状态" tabindex="-1">1. 服务与验证状态 <a class="header-anchor" href="#_1-服务与验证状态" aria-label="Permalink to &quot;1. 服务与验证状态&quot;">​</a></h2><p>当前开发服务已重启过：</p><ul><li>Server: <code>http://127.0.0.1:3000</code></li><li>Web: <code>http://127.0.0.1:5174</code></li><li>授权页：<code>http://127.0.0.1:5174/authorizations</code></li><li>设备页：<code>http://127.0.0.1:5174/devices</code></li></ul><p>最近验证：</p><ul><li><code>pnpm --filter @hs/server typecheck</code> 通过。</li><li><code>pnpm --filter @hs/web exec vite build</code> 通过。</li><li><code>/api/auth/status</code> 返回 <code>source=local_auth_file</code>，不再默认启动 mi-cli。</li><li><code>/api/user-devices/cards?online=1</code> 的 <code>sources</code> 现在只会是 <code>mi</code> / <code>adb</code>，不会再因为有 IP 生成 <code>lan</code>。</li><li><code>/api/user-devices/mi-candidates</code>： <ul><li>优先读 mi-cli 磁盘缓存：<code>source=mi_cli_disk_cache</code></li><li>后续 5 分钟命中内存缓存：<code>source=memory_cache</code></li></ul></li></ul><p>注意：</p><ul><li><code>pnpm --filter @hs/web build</code> 仍会被旧测试文件卡住，因为缺 <code>vitest</code> / <code>@vue/test-utils</code>。当前不急着处理测试，先用 <code>vite build</code> 做页面编译验证。</li><li>当前 git 工作区本来就是大面积未跟踪 / 迁移状态，不要按普通干净仓库假设处理。</li></ul><hr><h2 id="_2-授权中心现状" tabindex="-1">2. 授权中心现状 <a class="header-anchor" href="#_2-授权中心现状" aria-label="Permalink to &quot;2. 授权中心现状&quot;">​</a></h2><p>入口：</p><ul><li>新入口：<code>/authorizations</code></li><li>老入口 <code>/integrations</code> 已废弃并重定向到 <code>/authorizations</code></li><li><code>/integrations/mi-cli</code> 重定向到 <code>/authorizations/mi-cli</code></li></ul><p>页面结构：</p><ul><li>一级 tab： <ul><li>外部账号：<code>Mi</code> / <code>Bilibili</code></li><li>局域网账号：<code>ADB</code> / 串流 / SSH / FRP / SMB</li></ul></li></ul><p>用户已经纠正过命名：</p><ul><li>这里的“局域网账号”是授权归类，不等于设备来源叫 LAN。</li><li>对设备能力来源来说，必须说 <code>ADB</code>，不是 <code>LAN</code>。</li></ul><hr><h2 id="_3-mi-状态与候选设备缓存" tabindex="-1">3. Mi 状态与候选设备缓存 <a class="header-anchor" href="#_3-mi-状态与候选设备缓存" aria-label="Permalink to &quot;3. Mi 状态与候选设备缓存&quot;">​</a></h2><h3 id="_3-1-登录状态" tabindex="-1">3.1 登录状态 <a class="header-anchor" href="#_3-1-登录状态" aria-label="Permalink to &quot;3.1 登录状态&quot;">​</a></h3><p>已改文件：</p><ul><li><code>apps/server/src/auth/auth.controller.ts</code></li><li><code>packages/mi-cli/src/mi_cli/api/auth.py</code></li><li><code>apps/web/src/api/index.ts</code></li></ul><p>当前行为：</p><ul><li><code>/api/auth/status</code> 默认直接读取本地 <code>auth.json</code>。</li><li>返回 <code>source=local_auth_file</code>。</li><li>不启动 mi-cli，不联网。</li><li>只有 <code>?refresh=1</code> 才强制走 mi-cli 的 <code>login_status</code>。</li><li>mi-cli 内部也改成 cache-first： <ul><li>核心字段完整即可认作本地登录。</li><li>老缓存没有 <code>expireTime</code> 时也不再为了“显示登录状态”去联网。</li></ul></li></ul><p>这个改动是为了解决：点 Mi / 打开授权页时卡住几百毫秒甚至更久。</p><h3 id="_3-2-mi-候选设备" tabindex="-1">3.2 Mi 候选设备 <a class="header-anchor" href="#_3-2-mi-候选设备" aria-label="Permalink to &quot;3.2 Mi 候选设备&quot;">​</a></h3><p>已改文件：</p><ul><li><code>apps/server/src/devices/device.service.ts</code></li><li><code>apps/server/src/devices/device.controller.ts</code></li><li><code>apps/web/src/views/DevicesView.vue</code></li><li><code>apps/web/src/api/index.ts</code></li></ul><p>当前行为：</p><ul><li>编辑设备弹窗不再等待 <code>miCandidates()</code> 才打开。</li><li>弹窗先显示已有字段，Mi 候选后台加载。</li><li>当前已绑定的 <code>mi_did</code> 会先作为 fallback option 显示，不会空白。</li><li>后端 <code>mi-candidates</code> 优先读： <ol><li>5 分钟内存缓存</li><li>mi-cli 磁盘缓存 <code>~/.cache/mi-cli/devices.json</code></li><li>最后才启动 <code>mi-cli discover summary_only=true</code></li></ol></li></ul><p>用户观察到的卡顿原因：</p><ul><li>原来 <code>openEdit()</code> 每次都会 await <code>api.userDevices.miCandidates()</code>。</li><li>后端每次都会启动 <code>mi-cli discover</code>。</li><li>即使命中 mi-cli 自己的设备缓存，启动 Python / uv 本身也慢。</li></ul><hr><h2 id="_4-adb-当前边界" tabindex="-1">4. ADB 当前边界 <a class="header-anchor" href="#_4-adb-当前边界" aria-label="Permalink to &quot;4. ADB 当前边界&quot;">​</a></h2><p>这是本轮最重要的边界调整之一。</p><p>用户最终确认：</p><ul><li>ADB 授权页不是设备管理页。</li><li>ADB 授权页只保留一个 ADB 端点列表。</li><li>最多能自己填一个名字，改名，改 IP:端口。</li><li>具体映射绑定到哪个设备，去设备页做。</li></ul><p>当前 <code>/authorizations</code> 的 ADB 区：</p><ul><li>列表只显示： <ul><li>名称</li><li>地址</li><li>编辑 / 删除</li></ul></li><li>新增 / 编辑弹窗只保留： <ul><li>名称</li><li>IP:端口</li></ul></li><li>不再显示： <ul><li>房间</li><li>类型</li><li>单独 IP</li><li>在线状态</li><li>验证按钮</li><li>应用按钮</li><li>设备详情跳转</li></ul></li></ul><p>当前实现仍暂时复用 <code>user_devices</code> 表承载 ADB 端点：</p><ul><li>新增端点时默认： <ul><li><code>device_type=other</code></li><li><code>room_id=null</code></li><li><code>adb_ip=IP:端口</code></li><li><code>ip_address</code> 自动从端点拆 host</li></ul></li></ul><p>这只是临时承载。后续更干净的模型应该是拆出 <code>adb_endpoints</code> 或 <code>device_bindings</code>。</p><hr><h2 id="_5-设备管理当前边界" tabindex="-1">5. 设备管理当前边界 <a class="header-anchor" href="#_5-设备管理当前边界" aria-label="Permalink to &quot;5. 设备管理当前边界&quot;">​</a></h2><p>已改文件：</p><ul><li><code>apps/web/src/views/DevicesView.vue</code></li><li><code>apps/web/src/views/DeviceDetailView.vue</code></li><li><code>apps/server/src/devices/device-card-projection.ts</code></li></ul><p>当前定义：</p><ul><li><code>Mi</code> 是来源 / 能力绑定。</li><li><code>ADB</code> 是来源 / 能力绑定。</li><li><code>IP</code> 只是网络地址，用于在线检测，不是来源。</li><li>废除设备侧 <code>LAN</code> 说法。</li></ul><p>具体变化：</p><ul><li>设备列表 source tag： <ul><li>有 <code>mi_did</code> 显示 <code>Mi</code></li><li>有 <code>adb_ip</code> 显示 <code>ADB</code></li><li>只有 <code>ip_address</code> 不显示来源 tag</li></ul></li><li>设备详情： <ul><li><code>LAN: xxx</code> 改成 <code>ADB: xxx</code></li><li><code>LAN · n</code> 能力分组改成 <code>ADB · n</code></li><li>“LAN 控制来源”文案改成 “ADB 能力来源”</li></ul></li><li>后端 <code>DeviceCardProjection.sources</code>： <ul><li>以前：有 <code>ip_address</code> 或 <code>adb_ip</code> 就加 <code>lan</code></li><li>现在：只有 <code>adb_ip</code> 才加 <code>adb</code></li></ul></li></ul><hr><h2 id="_6-当前数据" tabindex="-1">6. 当前数据 <a class="header-anchor" href="#_6-当前数据" aria-label="Permalink to &quot;6. 当前数据&quot;">​</a></h2><p>v2 DB：</p><ul><li><code>D:\\files\\HomeSense-Studio-v2\\data\\homesense-v2.db</code></li></ul><p>已从 legacy 恢复的数据：</p><ul><li>房间：3</li><li>设备：6</li><li>ADB 端点 / ADB 绑定字段： <ul><li><code>客厅机顶盒</code> — <code>192.168.31.91:5555</code></li><li><code>华为手机</code> — <code>192.168.31.253:5555</code></li><li><code>红米手机</code> — <code>192.168.31.124:5555</code></li></ul></li><li>Mi 绑定： <ul><li>客厅电视</li><li>客厅机顶盒</li><li>两个小爱音箱</li></ul></li></ul><p>注意：</p><ul><li>这 3 个 ADB 现在仍是 <code>user_devices</code> 里的记录。</li><li>用户希望后续“端点”和“设备绑定”分开，这块还没拆表。</li></ul><hr><h2 id="_7-数字孪生方向" tabindex="-1">7. 数字孪生方向 <a class="header-anchor" href="#_7-数字孪生方向" aria-label="Permalink to &quot;7. 数字孪生方向&quot;">​</a></h2><p>用户最新方向：</p><ul><li>先造 2D 图。</li><li>不做 3D。</li><li>绑定关系去详情页看，不堆在图上。</li><li>2D 图第一版只表达： <ul><li>房间</li><li>设备位置</li><li>设备类型</li><li>在线 / 离线</li><li>当前选中设备</li></ul></li></ul><p>建议下一刀：</p><ul><li>重做 <code>/devices</code>。</li><li>不再以卡片网格作为主视图。</li><li>改成：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>[ 房间筛选 / 状态筛选 / 搜索 ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌───────────────────────────────┬────────────────────┐</span></span>
<span class="line"><span>│                               │  选中设备摘要       │</span></span>
<span class="line"><span>│        2D 房间画布             │  名称 / 状态 / 入口 │</span></span>
<span class="line"><span>│                               │                    │</span></span>
<span class="line"><span>│  ┌──────── 客厅 ────────┐      │  详情页查看绑定     │</span></span>
<span class="line"><span>│  │ TV     STB    音箱   │      │  Mi / ADB / IP      │</span></span>
<span class="line"><span>│  └─────────────────────┘      │                    │</span></span>
<span class="line"><span>│                               │                    │</span></span>
<span class="line"><span>│  ┌──────── 餐厅 ────────┐      │                    │</span></span>
<span class="line"><span>│  │ 小爱音箱             │      │                    │</span></span>
<span class="line"><span>│  └─────────────────────┘      │                    │</span></span>
<span class="line"><span>└───────────────────────────────┴────────────────────┘</span></span></code></pre></div><p>第一版不要做：</p><ul><li>拖拽</li><li>精准户型</li><li>GPS 定位</li><li>复杂连线</li><li>在图上塞绑定字段</li></ul><p>第一版应该做：</p><ul><li>按房间渲染区域。</li><li>每个设备是房间内一个节点。</li><li>节点显示图标 / 名称 / 在线状态。</li><li>点击节点选中，右侧显示摘要和“进入详情”。</li><li>详情页继续承接绑定查看和编辑。</li></ul><hr><h2 id="_8-gps-问题结论" tabindex="-1">8. GPS 问题结论 <a class="header-anchor" href="#_8-gps-问题结论" aria-label="Permalink to &quot;8. GPS 问题结论&quot;">​</a></h2><p>用户问过：GPS 能不能拿，拿到了有没有用。</p><p>结论：</p><ul><li>手机 GPS 可以拿，但需要手机端配合： <ul><li>自研 Android App</li><li>Tasker / MacroDroid</li><li>Home Assistant Companion App</li><li>生态接口，但通常不稳定</li></ul></li><li>电视 / 盒子 / 音箱 / 路由器基本没有 GPS。</li><li>GPS 对室内房间级数字孪生帮助不大，精度不够。</li><li>GPS 更适合： <ul><li>判断人是否在家</li><li>回家 / 离家自动化</li><li>家庭成员大概位置</li></ul></li></ul><p>当前数字孪生不要依赖 GPS。</p><p>设备位置先手动放到房间里。</p><hr><h2 id="_9-测试态度" tabindex="-1">9. 测试态度 <a class="header-anchor" href="#_9-测试态度" aria-label="Permalink to &quot;9. 测试态度&quot;">​</a></h2><p>用户问过 <code>vitest / @vue/test-utils</code> 是否必要。</p><p>当前判断：</p><ul><li>它们是测试框架，不是运行时依赖。</li><li>旧测试是否正确还不确定。</li><li>v2 当前正在重排产品结构，不急着补测试依赖。</li><li>不建议为了让测试过而固定旧结构。</li><li>当前验证方式： <ul><li>server: <code>pnpm --filter @hs/server typecheck</code></li><li>web: <code>pnpm --filter @hs/web exec vite build</code></li></ul></li></ul><p>后续如果要恢复测试：</p><ul><li>加 devDependencies： <ul><li><code>vitest</code></li><li><code>@vue/test-utils</code></li><li><code>jsdom</code> 或 <code>happy-dom</code></li></ul></li><li>或拆 <code>tsconfig.app.json</code>，让生产 build 排除 <code>*.test.ts</code>。</li></ul><hr><h2 id="_10-下一步建议" tabindex="-1">10. 下一步建议 <a class="header-anchor" href="#_10-下一步建议" aria-label="Permalink to &quot;10. 下一步建议&quot;">​</a></h2><p>优先级按用户最新方向排序：</p><ol><li>重做 <code>/devices</code> 为 2D 房间画布。</li><li>保留设备详情页作为绑定 / 能力查看入口。</li><li>从 <code>user_devices</code> 里拆出 ADB 端点模型： <ul><li><code>adb_endpoints</code></li><li>或 <code>device_bindings</code></li></ul></li><li>设备页中 ADB 绑定不要手填散落字段，应该从 ADB 端点列表里选择。</li><li>数字孪生 2D 图先用 rooms + devices 的现有数据渲染，不做复杂编辑。</li><li>等 UI 稳定后再考虑测试框架和 tsconfig 拆分。</li></ol><hr><h2 id="_11-关键提醒" tabindex="-1">11. 关键提醒 <a class="header-anchor" href="#_11-关键提醒" aria-label="Permalink to &quot;11. 关键提醒&quot;">​</a></h2><ul><li>不要再把 <code>LAN</code> 当设备来源。</li><li><code>IP</code> 只是网络状态字段。</li><li><code>ADB</code> 才是能力来源。</li><li>授权中心 ADB 页只管端点，不管设备绑定。</li><li>设备绑定在详情页看。</li><li>2D 数字孪生是下一刀，先做房间和设备节点，不要先做复杂能力图。</li><li>Mi 状态和 Mi 候选都已经做 cache-first，不要再把打开页面绑到 mi-cli 启动上。</li></ul>`,92)])])}const m=l(d,[["render",a]]);export{h as __pageData,m as default};
